package com.bank.dedup;

import java.util.Set;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class DuplicateDemo {

    private static final Logger log = Logger.getLogger(DuplicateDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        String[] transactionIds = {
            "TXN-1001", "TXN-1002", "TXN-1001",  // TXN-1001 repeats
            "TXN-1003", "TXN-1002", "TXN-1002"   // TXN-1002 repeats twice
        };

        DuplicateDetector detector = new DuplicateDetector();
        Set<String> duplicates = detector.findDuplicates(transactionIds);

        if (duplicates.isEmpty()) {
            log.info("No duplicate transactions — safe to post.");
        } else {
            log.warning(() -> "Duplicate transaction IDs detected: " + duplicates);
            log.severe("Blocking batch to prevent double posting.");
        }
    }
}

// ─── Would be in service/DuplicateDetector.java in a real project ───
class DuplicateDetector {

    private static final Logger log = Logger.getLogger(DuplicateDetector.class.getName());

    // Return the set of IDs that appeared more than once.
    Set<String> findDuplicates(String[] transactionIds) {
        Set<String> seen = new java.util.HashSet<>();        // already encountered
        Set<String> duplicates = new java.util.LinkedHashSet<>(); // reported once, keeps order

        for (String id : transactionIds) {
            // add() returns false if the element was already present.
            if (!seen.add(id)) {
                duplicates.add(id); // first and later repeats all land here once
                log.fine(() -> "Duplicate spotted: " + id);
            }
        }
        log.info(() -> "Scanned " + transactionIds.length + " IDs, found "
                + duplicates.size() + " duplicate value(s).");
        return duplicates;
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
